def schedule_slots(start_hour, end_hour, duration, busy):
    slots = []
    t = start_hour * 60
    while t + duration <= end_hour * 60:
        if all(t + duration <= b0 or t >= b1 for b0, b1 in busy):
            slots.append((t // 60, t % 60))
        t += 15
    return slots

def update_settings(conn, user_id, changes):
    editable = {"theme": str, "language": str, "page_size": int}
    sets, values = [], []
    for key, value in changes.items():
        kind = editable.get(key)
        if kind is None:
            continue
        sets.append(f"{key} = ?")
        values.append(kind(value))
    if not sets:
        return 0
    values.append(user_id)
    cur = conn.execute("UPDATE settings SET " + ", ".join(sets) + " WHERE user_id = ?", values)
    conn.commit()
    return cur.rowcount

@app.route("/polls/<int:poll_id>/vote", methods=["POST"])
def vote(poll_id):
    voter = session.get("user_id")
    option_id = request.form.get("option", type=int)
    if voter is None or option_id is None:
        return jsonify(error="sign in and choose an option"), 400
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute("SELECT closes_at FROM polls WHERE id = %s", (poll_id,))
        poll = cur.fetchone()
        if poll is None:
            abort(404)
        if poll[0] < datetime.utcnow():
            return jsonify(error="poll is closed"), 409
        cur.execute("SELECT 1 FROM poll_options WHERE id = %s AND poll_id = %s", (option_id, poll_id))
        if cur.fetchone() is None:
            return jsonify(error="unknown option"), 400
        cur.execute("SELECT option_id FROM votes WHERE poll_id = %s AND voter_id = %s", (poll_id, voter))
        previous = cur.fetchone()
        if previous is None:
            cur.execute("INSERT INTO votes (poll_id, option_id, voter_id) VALUES (%s, %s, %s)", (poll_id, option_id, voter))
        else:
            cur.execute("UPDATE votes SET option_id = %s WHERE poll_id = %s AND voter_id = %s", (option_id, poll_id, voter))
        cur.execute("SELECT option_id, COUNT(*) FROM votes WHERE poll_id = %s GROUP BY option_id", (poll_id,))
        counts = dict(cur.fetchall())
    return jsonify(poll=poll_id, counts=counts, changed=previous is not None)

def initials(full_name, limit=3):
    letters = [part[0].upper() for part in full_name.split() if part]
    if not letters:
        raise ValueError("empty name")
    return "".join(letters[:limit])

def split_camel(name):
    words, current = [], ""
    for ch in name:
        if ch.isupper() and current and not current[-1].isupper():
            words.append(current)
            current = ch
        else:
            current += ch
    return words + [current] if current else words

