def merge_customers(session, keep_id, duplicate_id, actor_id):
    if keep_id == duplicate_id:
        raise ValueError("cannot merge a customer with itself")
    keep = session.get(Customer, keep_id)
    duplicate = session.get(Customer, duplicate_id)
    if keep is None or duplicate is None:
        raise LookupError("customer not found")
    moved_orders = session.query(Order).filter(Order.customer_id == duplicate_id).update({"customer_id": keep_id})
    moved_notes = session.query(Note).filter(Note.customer_id == duplicate_id).update({"customer_id": keep_id})
    for address in list(duplicate.addresses):
        exists = (
            session.query(Address)
            .filter(Address.customer_id == keep_id, Address.line1 == address.line1, Address.postcode == address.postcode)
            .first()
        )
        if exists is None:
            address.customer_id = keep_id
        else:
            session.delete(address)
    keep.loyalty_points = (keep.loyalty_points or 0) + (duplicate.loyalty_points or 0)
    duplicate.merged_into = keep_id
    duplicate.active = False
    session.add(AuditEntry(actor_id=actor_id, action="merge_customers", target=f"{duplicate_id}->{keep_id}"))
    session.commit()
    return {"orders": moved_orders, "notes": moved_notes}

