def parse_table(text, schema):
    rows, current, field, quoted = [], [], "", False
    i = 0
    while i < len(text):
        ch = text[i]
        if quoted:
            if ch == chr(34):
                if i + 1 < len(text) and text[i + 1] == chr(34):
                    field += chr(34)
                    i += 1
                else:
                    quoted = False
            else:
                field += ch
        elif ch == chr(34):
            quoted = True
        elif ch == ",":
            current.append(field)
            field = ""
        elif ch == chr(10):
            current.append(field)
            rows.append(current)
            current, field = [], ""
        else:
            field += ch
        i += 1
    if field or current:
        current.append(field)
        rows.append(current)
    header, body = rows[0], rows[1:]
    converters = {name: schema.get(name, str) for name in header}
    return [{name: converters[name](value) for name, value in zip(header, row)} for row in body]

def layout_table(rows, columns, max_width=100, padding=1):
    headers = [c["title"] for c in columns]
    keys = [c["key"] for c in columns]
    aligns = [c.get("align", "left") for c in columns]
    cells = [[str(row.get(k, "")) for k in keys] for row in rows]
    widths = [max([len(h)] + [len(r[i]) for r in cells]) for i, h in enumerate(headers)]
    available = max_width - padding * 2 * len(columns) - (len(columns) - 1)
    while sum(widths) > available and max(widths) > 8:
        widest = widths.index(max(widths))
        widths[widest] -= 1

    def fit(text, width):
        return text if len(text) <= width else text[: max(width - 1, 1)] + "~"

    def align(text, width, how):
        text = fit(text, width)
        if how == "right":
            return text.rjust(width)
        if how == "center":
            return text.center(width)
        return text.ljust(width)

    pad = " " * padding
    separator = "+".join("-" * (w + padding * 2) for w in widths)
    lines = [
        "|".join(pad + align(h, w, "center") + pad for h, w in zip(headers, widths)),
        separator,
    ]
    for row in cells:
        lines.append("|".join(pad + align(v, w, a) + pad for v, w, a in zip(row, widths, aligns)))
    totals = [c for c in columns if c.get("total")]
    if totals:
        lines.append(separator)
        summary = []
        for c, w, a in zip(columns, widths, aligns):
            if c.get("total"):
                value = sum(float(r.get(c["key"], 0) or 0) for r in rows)
                summary.append(pad + align(f"{value:,.2f}", w, "right") + pad)
            else:
                summary.append(pad + " " * w + pad)
        lines.append("|".join(summary))
    return chr(10).join(lines)

