@app.route("/api/cart", methods=["GET", "POST", "DELETE"])
def cart():
    db = get_db()
    user_id = g.user["id"]
    if request.method == "POST":
        data = request.get_json() or {}
        sku, qty = data.get("sku"), int(data.get("qty", 1))
        product = db.execute("SELECT stock FROM products WHERE sku = ?", (sku,)).fetchone()
        if product is None:
            return jsonify(error="unknown product"), 404
        if qty < 1 or qty > product["stock"]:
            return jsonify(error="invalid quantity"), 400
        db.execute(
            "INSERT INTO cart_items (user_id, sku, qty) VALUES (?, ?, ?) "
            "ON CONFLICT (user_id, sku) DO UPDATE SET qty = qty + excluded.qty",
            (user_id, sku, qty),
        )
    elif request.method == "DELETE":
        db.execute("DELETE FROM cart_items WHERE user_id = ?", (user_id,))
    db.commit()
    rows = db.execute(
        "SELECT c.sku, c.qty, p.name, p.price FROM cart_items c JOIN products p ON p.sku = c.sku WHERE c.user_id = ?",
        (user_id,),
    ).fetchall()
    total = sum(r["qty"] * r["price"] for r in rows)
    return jsonify(items=[dict(r) for r in rows], total=round(total, 2))

