def validate_schedule(shifts, min_rest_hours=11, max_week_hours=48):
    problems = []
    by_person = {}
    for shift in shifts:
        by_person.setdefault(shift["person"], []).append(shift)
    for person, items in by_person.items():
        items.sort(key=lambda s: s["start"])
        week_hours = {}
        for previous, current in zip(items, items[1:]):
            rest = (current["start"] - previous["end"]).total_seconds() / 3600
            if rest < min_rest_hours:
                problems.append(f"{person}: only {rest:.1f}h rest before {current['start']:%a %H:%M}")
        for item in items:
            week = item["start"].isocalendar()[1]
            hours = (item["end"] - item["start"]).total_seconds() / 3600
            week_hours[week] = week_hours.get(week, 0) + hours
        for week, hours in week_hours.items():
            if hours > max_week_hours:
                problems.append(f"{person}: {hours:.0f}h in week {week}")
    return problems

def budget_report(entries, budgets):
    spent = {}
    for entry in entries:
        spent[entry["category"]] = spent.get(entry["category"], 0) + entry["amount"]
    report = []
    for category, limit in sorted(budgets.items()):
        used = spent.get(category, 0)
        remaining = limit - used
        report.append({
            "category": category,
            "limit": limit,
            "spent": round(used, 2),
            "remaining": round(remaining, 2),
            "status": "over" if remaining < 0 else "near" if remaining < limit * 0.1 else "ok",
        })
    unbudgeted = {c: round(v, 2) for c, v in spent.items() if c not in budgets}
    total_limit = sum(budgets.values())
    total_spent = sum(spent.values())
    return {"rows": report, "unbudgeted": unbudgeted, "total_limit": total_limit, "total_spent": round(total_spent, 2)}

