def publish_roster(session, week_start, manager_id, notify=True):
    week_end = week_start + timedelta(days=7)
    manager = session.get(Employee, manager_id)
    if manager is None or manager.role != "manager":
        raise PermissionError("only managers can publish a roster")
    shifts = (
        session.query(Shift)
        .filter(Shift.start >= week_start, Shift.start < week_end, Shift.location_id == manager.location_id)
        .order_by(Shift.start)
        .all()
    )
    if not shifts:
        raise ValueError("no shifts to publish")
    problems = []
    by_employee = {}
    for shift in shifts:
        if shift.employee_id is None:
            problems.append(f"shift {shift.id} has nobody assigned")
            continue
        by_employee.setdefault(shift.employee_id, []).append(shift)
    for employee_id, items in by_employee.items():
        hours = sum((s.end - s.start).total_seconds() for s in items) / 3600
        employee = session.get(Employee, employee_id)
        if hours > employee.max_weekly_hours:
            problems.append(f"{employee.name} is over their weekly hours ({hours:.0f})")
        leave = (
            session.query(Leave)
            .filter(Leave.employee_id == employee_id, Leave.start < week_end, Leave.end > week_start, Leave.approved.is_(True))
            .count()
        )
        if leave:
            problems.append(f"{employee.name} has approved leave this week")
    if problems:
        return {"published": False, "problems": problems}
    for shift in shifts:
        shift.published = True
    session.add(RosterVersion(location_id=manager.location_id, week_start=week_start, published_by=manager_id, shifts=len(shifts)))
    if notify:
        for employee_id in by_employee:
            session.add(Message(recipient_id=employee_id, subject="New roster", body=f"Your roster for {week_start:%d %b} is ready"))
    session.commit()
    return {"published": True, "shifts": len(shifts), "employees": len(by_employee)}

