def run_vending(events, prices, stock):
    if not prices:
        raise ValueError("no prices")
    credit = 0
    log = []
    sales = {}
    for event in events:
        kind = event[0]
        if kind == "coin":
            value = event[1]
            if value not in (5, 10, 25, 100):
                log.append(("rejected", value))
                continue
            credit += value
            log.append(("credit", credit))
        elif kind == "select":
            item = event[1]
            if item not in prices:
                log.append(("unknown", item))
            elif stock.get(item, 0) <= 0:
                log.append(("sold_out", item))
            elif credit < prices[item]:
                log.append(("need", prices[item] - credit))
            else:
                credit -= prices[item]
                stock[item] -= 1
                sales[item] = sales.get(item, 0) + 1
                log.append(("vend", item))
                change = []
                for coin in (100, 25, 10, 5):
                    while credit >= coin:
                        credit -= coin
                        change.append(coin)
                if change:
                    log.append(("change", change))
        elif kind == "refund":
            change = []
            for coin in (100, 25, 10, 5):
                while credit >= coin:
                    credit -= coin
                    change.append(coin)
            log.append(("refund", change))
    revenue = sum(prices[i] * n for i, n in sales.items())
    empty = [i for i, n in stock.items() if n <= 0]
    return {"log": log, "sales": sales, "revenue": revenue, "remaining_credit": credit, "empty": empty}

