def chunk_text(text, size, overlap=0):
    if size <= overlap:
        raise ValueError("overlap must be smaller than size")
    chunks, start = [], 0
    while start < len(text):
        chunks.append(text[start:start + size])
        start += size - overlap
    return chunks

def build_calendar(year, month, events):
    first_weekday, days = calendar.monthrange(year, month)
    weeks, week = [], [None] * first_weekday
    by_day = {}
    for event in events:
        if event["date"].year == year and event["date"].month == month:
            by_day.setdefault(event["date"].day, []).append(event["title"])
    for day in range(1, days + 1):
        week.append({"day": day, "events": by_day.get(day, [])})
        if len(week) == 7:
            weeks.append(week)
            week = []
    if week:
        weeks.append(week + [None] * (7 - len(week)))
    return weeks

def simulate_queue(arrivals, service_time, servers=1):
    free_at = [0.0] * servers
    waits = []
    for arrival in sorted(arrivals):
        idx = min(range(servers), key=lambda i: free_at[i])
        start = max(arrival, free_at[idx])
        waits.append(start - arrival)
        free_at[idx] = start + service_time
    if not waits:
        return {"served": 0, "mean_wait": 0.0, "max_wait": 0.0}
    return {
        "served": len(waits),
        "mean_wait": sum(waits) / len(waits),
        "max_wait": max(waits),
        "busy_until": max(free_at),
    }

def group_consecutive(numbers):
    groups = []
    for n in sorted(set(numbers)):
        if groups and n == groups[-1][-1] + 1:
            groups[-1].append(n)
        else:
            groups.append([n])
    return [(g[0], g[-1]) if len(g) > 1 else (g[0],) for g in groups]

