    cur.execute("SELECT sku, qty FROM cart_items WHERE user_id = %d" % user_id)
    items = cur.fetchall()
    if not items:
        flash("your cart is empty")
        return redirect("/cart")
    total = 0
    lines = []
    for sku, qty in items:
        cur.execute("SELECT price, stock FROM products WHERE sku = '%s'" % sku)
        price, stock = cur.fetchone()
        if stock < qty:
            flash("not enough stock for " + sku)
            return redirect("/cart")
        total += price * qty
